<script setup lang="ts">
import { computed, ref, watch, nextTick } from 'vue';
import { Play, Square, Search, Code2, PencilLine, Eye, CheckCircle2 } from 'lucide-vue-next';
import ApiMaterialPanel from './ApiMaterialPanel.vue';
import ModalFrame from './ModalFrame.vue';
import { apiTestMaterials as apiMaterials, API_CASE_COUNT } from './campus-handoff';
import type { CampusTaskStore, CaseNote, CheckResult } from './task-store';
import type { EndpointConfig } from './types';
const props = defineProps<{ store: CampusTaskStore; busy: boolean; running: boolean; waiting?: boolean; runningId: string | null; progress: number }>();
const emit = defineEmits<{ parse: []; generate: []; run: [ids: string[]]; stop: []; edit: [config: EndpointConfig, note: CaseNote]; manual: [id: string, result: CheckResult] }>();
const search = ref(''), group = ref('all'), inspected = ref<string | null>(null), editing = ref<{ config: EndpointConfig; note: CaseNote } | null>(null), error = ref('');
const tableViewport=ref<HTMLElement|null>(null), panel=ref<HTMLElement|null>(null);
watch(()=>props.running,async value=>{if(value){await nextTick();panel.value?.scrollIntoView({block:'start',behavior:'instant'});}});
watch(()=>props.runningId,async id=>{await nextTick();if(!id || !tableViewport.value)return;const viewport=tableViewport.value;const row=Array.from(viewport.querySelectorAll<HTMLElement>('tr[data-case-id]')).find(el=>el.dataset.caseId===id);if(row){const header=viewport.querySelector('thead')?.getBoundingClientRect().height || 0;viewport.scrollTop+=row.getBoundingClientRect().top-viewport.getBoundingClientRect().top-header;}});
const groups = [...new Set(apiMaterials.map(m=>m.group))];
const visible = computed(() => props.store.apiCases.filter(c => { const material = apiMaterials.find(m=>`delivery-${m.id}`===c.id)!; return (group.value==='all'||material.group===group.value) && `${c.name} ${c.path} ${c.method}`.toLowerCase().includes(search.value.toLowerCase()); }));
const sample = computed(() => inspected.value ? props.store.apiResults[inspected.value] : null);
const selectedCase = computed(() => props.store.apiCases.find(c=>c.id===inspected.value));
function edit(id: string) { const config=props.store.apiCases.find(c=>c.id===id)!; editing.value={config:{...config},note:{...props.store.apiNotes[id]||{note:'',checkpoint:'',result:'pending'}}}; error.value=''; }
function saveEdit() { const e=editing.value; if (!e) return; if (!e.config.name.trim() || e.config.name.length>80 || !Number.isInteger(e.config.status) || e.config.status<100 || e.config.status>599 || !Number.isFinite(e.config.budget) || e.config.budget<1 || e.config.budget>60000) {error.value='名称、预期状态码或响应阈值无效。';return;} emit('edit',e.config,e.note); editing.value=null; }
const resultName = (id: string) => !props.store.apiResults[id] ? '待测试' : ({passed:'通过',failed:'未通过',cancelled:'已取消'})[props.store.apiResults[id].outcome];
</script>
<template><div class="section-intro"><div><span class="eyebrow">API MATERIAL / CONTRACT VERIFICATION</span><h1>从交付材料，生成可解释的测试。</h1><p>先解析、再生成、最后手动执行；每一次响应与断言都有对应的用例。</p></div><span class="badge">{{ Object.keys(store.apiResults).length }} / {{ store.apiCases.length || apiMaterials.length }} 项有执行记录</span></div><ApiMaterialPanel :parsed="!!store.apiParsedAt" :generated="!!store.apiGeneratedAt" :busy="busy" @parse="emit('parse')" @generate="emit('generate')"/>
<section ref="panel" class="panel api-test-panel" :class="{'api-executing':running}"><div class="panel-heading"><h2><Code2 :size="18"/>API测试用例 · {{API_CASE_COUNT}} 项</h2><div class="toolbar-actions"><button v-if="running" class="secondary" @click="emit('stop')"><Square :size="14"/>停止API测试</button><button class="primary" :disabled="busy || !store.apiGeneratedAt || !visible.length" @click="emit('run',visible.map(c=>c.id))"><Play :size="15"/>{{ group==='all' && !search ? '运行全部API' : '运行筛选用例' }}</button></div></div><div v-if="running" class="run-progress"><div><span>{{ runningId ? store.apiCases.find(c=>c.id===runningId)?.name : '正在整理执行记录' }}</span><b>{{ Math.round(progress) }}%</b></div><div class="progress-track"><i :style="{width:`${progress}%`}"/></div><p>{{ waiting ? '模拟网络等待…进度稍停后继续（本地演示）' : '快速验证中 · 含短暂网络波动演示，不发送真实测试请求' }}</p></div><div v-if="!store.apiGeneratedAt" class="empty-state"><Code2 :size="36"/><h3>用例尚未生成</h3><p>先解析上方API材料，再点击生成测试用例。<br/>生成不会自动执行任何接口测试。</p></div><template v-else><div class="api-filters"><label><Search :size="15"/><input v-model="search" :disabled="busy" aria-label="搜索API用例" placeholder="搜索接口名称、路径或方法"/></label><select v-model="group" :disabled="busy" aria-label="筛选API分组"><option value="all">全部业务分组</option><option v-for="g in groups" :key="g" :value="g">{{g}}</option></select><span>当前 {{ visible.length }} 项</span></div><div ref="tableViewport" class="api-table-wrap"><table class="api-table"><thead><tr><th>接口 / 用例</th><th>方法与路径</th><th>预期</th><th>执行结果</th><th>操作</th></tr></thead><tbody><tr v-for="item in visible" :key="item.id" :data-case-id="item.id" :class="{running:runningId===item.id}"><td><b>{{ item.name }}</b><small>{{ item.id }}</small></td><td><span class="method" :class="item.method?.toLowerCase()">{{item.method}}</span><code>{{ item.path }}</code></td><td><span>HTTP {{ item.status }}</span><small>≤ {{ item.budget }} ms</small></td><td><span class="badge" :class="{good:store.apiResults[item.id]?.outcome==='passed',issue:store.apiResults[item.id]?.outcome==='failed',muted:!store.apiResults[item.id]}">{{ runningId===item.id ? '正在核验' : resultName(item.id) }}</span><small v-if="store.apiResults[item.id]">{{ store.apiResults[item.id].elapsedMs.toFixed(1) }} ms · {{ new Date(store.apiResults[item.id].at).toLocaleTimeString('zh-CN',{hour12:false}) }}</small><small v-if="store.apiNotes[item.id]?.checkpoint">补充检查：{{store.apiNotes[item.id].result==='passed'?'通过':store.apiNotes[item.id].result==='issue'?'需整改':'待人工确认'}}</small></td><td><div class="row-actions"><button class="text-button" :disabled="busy" :aria-label="`运行${item.name}`" @click="emit('run',[item.id])"><Play :size="13"/></button><button class="text-button" :disabled="busy" :aria-label="`编辑${item.name}`" @click="edit(item.id)"><PencilLine :size="13"/></button><button class="text-button" :disabled="busy || !store.apiResults[item.id]" :aria-label="`查看${item.name}结果`" @click="inspected=item.id"><Eye :size="14"/></button></div></td></tr><tr v-if="running" class="api-scroll-tail" aria-hidden="true"><td colspan="5"/></tr></tbody></table><div v-if="!visible.length" class="empty-state">没有匹配的接口用例。</div></div></template></section>
<ModalFrame v-if="inspected && sample" title="API用例执行证据" wide @close="inspected=null"><div class="api-evidence"><div class="material-title"><h3>{{ selectedCase?.name }}</h3><span class="badge">HTTP {{sample.status}} · {{sample.elapsedMs}} ms</span></div><code>{{sample.requestId}}</code><p class="evidence-source">证据来源：本地契约模型；未向校园业务服务发送测试请求。</p><div class="api-assertions"><div v-for="check in sample.checks" :key="check.label"><CheckCircle2 :size="15"/><span>{{check.label}}</span><b>{{check.passed?'通过':'未通过'}}</b></div></div><h4>本次用例请求参数（本地模型）</h4><pre>{{JSON.stringify(apiMaterials.find(m=>`delivery-${m.id}`===inspected)?.request,null,2)}}</pre><h4>固定响应与断言证据</h4><pre>{{sample.preview || '无响应内容'}}</pre><section v-if="store.apiNotes[inspected]?.checkpoint" class="manual-check"><h4>补充人工检查点</h4><p>{{store.apiNotes[inspected].checkpoint}}</p><button class="secondary" :disabled="busy" @click="emit('manual',inspected,'passed')">确认补充检查通过</button><button class="secondary" :disabled="busy" @click="emit('manual',inspected,'issue')">记录需整改</button><span class="badge">{{store.apiNotes[inspected].result==='passed'?'通过':store.apiNotes[inspected].result==='issue'?'需整改':'待确认'}}</span></section></div></ModalFrame>
<ModalFrame v-if="editing" title="调整API测试用例" @close="editing=null"><form class="case-editor" @submit.prevent="saveEdit"><label>用例名称<input v-model="editing.config.name" aria-label="用例名称" maxlength="80"/></label><div class="editor-grid"><label>预期状态码<input type="number" v-model.number="editing.config.status" aria-label="预期状态码" min="100" max="599"/></label><label>耗时预算（ms）<input type="number" v-model.number="editing.config.budget" aria-label="耗时预算" min="1" max="60000"/></label></div><label>用例备注<textarea v-model="editing.note.note" aria-label="用例备注" maxlength="1000" rows="2"/></label><label>补充人工检查点<textarea v-model="editing.note.checkpoint" aria-label="补充人工检查点" maxlength="1000" rows="2"/></label><p>接口路径、方法及交付原始契约保持不变；保存调整会清除该用例的旧结果，补充检查点需人工确认。</p><p v-if="error" role="alert" class="inline-error">{{error}}</p><button class="primary" type="submit" :disabled="busy">保存用例调整</button></form></ModalFrame>
</template>
<style scoped>
.api-test-panel { scroll-margin-top:14px; }
.api-table-wrap { max-height:440px; overflow:auto; position:relative; scroll-behavior:auto; }
.api-table thead th { position:sticky; top:0; z-index:2; }
.api-table tr.running { background:#e4efdc; box-shadow:inset 4px 0 #25634f; }
.api-table tr.running td { color:#315b40; }
.api-scroll-tail td { height:440px; padding:0; border:0; }
.run-progress { background:#f3f8ef; padding-top:16px; margin-bottom:16px; }
.run-progress > div:first-child span { color:#28563d; font-size:14px; font-weight:600; }
</style>
